/* The values of a list option, as the text of the application option */
template <typename T>
std::string join_values(const std::vector<T>& values) {
  std::ostringstream text;
  for (size_t i = 0; i < values.size(); ++i) {
    text << (0 == i ? "" : " ") << values[i];
  }
  return text.str();
}

